function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
function colLetter(i) { let n = i + 1, out = ''; while (n > 0) { const m = (n - 1) % 26; out = String.fromCharCode(65 + m) + out; n = Math.floor((n - 1) / 26); } return out; }
const yes = function (x) { return s(x).toLowerCase() === 'yes'; };
const hdr = (($('GET header').first().json.values || [[]])[0] || []).map(s);
const C = {}; for (const h of ['pause', 'next_action', 'match_type', 'notes']) { const i = hdr.indexOf(h); if (i < 0) { throw new Error('ABORT: PIPELINE column missing ' + h); } C[h] = colLetter(i); }
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 4600) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }
// women-only / women-led funds
const FUNDS = new Set(['rebalance', 'colossaventures', 'shecapital', 'borskifund']);
// startups with a woman in the cap table - deck review 11 Sep, confirmed by the user
const WOMEN = new Set(['healthymaster', 'hyrgpt', 'serveamigo', 'bodybeyond', 'clikd', 'doffair', 'ekosight', 'fuskiai', 'luxova', 'mysoul', 'orbislives', 'roadathena', 'sahaj', 'talentrecruit', 'vilvaai', 'sugarsdaddy']);
const why = 'women-only fund, startup has no woman in the cap table (deck review, user 11 Sep)';
const data = [], drops = [], kept = [];
for (const p of pipe) { if (yes(p.deal_shared) || yes(p.pause)) { continue; } const ik = nz(p.investor); if (!FUNDS.has(ik)) { continue; }
  const sk = nz(p.startup); const rn = p.row_number; if (!rn) { throw new Error('ABORT: row without row_number'); }
  if (WOMEN.has(sk)) { kept.push([rn, s(p.deal_id), s(p.startup), s(p.investor), s(p.next_due)]); continue; }
  const n = s(p.notes);
  data.push({ range: 'PIPELINE!' + C.pause + rn, values: [['Yes']] }, { range: 'PIPELINE!' + C.next_action + rn, values: [['DROPPED - not per strategy']] },
    { range: 'PIPELINE!' + C.match_type + rn, values: [['Not per strategy: ' + why]] }, { range: 'PIPELINE!' + C.notes + rn, values: [[(n ? n + ' | ' : '') + 'DROPPED 2026-09-11 - ' + why]] });
  drops.push([rn, s(p.deal_id), s(p.startup), s(p.investor), s(p.next_due)]); }
if (drops.length > 60) { throw new Error('ABORT: ' + drops.length + ' drops exceeds guard (expected about 51)'); }
if (!data.length) { data.push({ range: 'PIPELINE!' + C.pause + '1', values: [['pause']] }); }
return [{ json: { pipeline_rows: pipe.length, to_drop: drops.length, kept_count: kept.length, drops: drops, kept: kept, data: data } }];

